UPDATE plt_migration_batch
SET batch_status = #{update.targetStatus},
    source_count = #{update.sourceCount},
    failure_code = #{update.failureCode},
    version = version + 1,
    update_time = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{update.tenantId}
  AND id = #{update.batchId}
  AND batch_status = #{update.expectedStatus}
  AND version = #{update.expectedVersion}
  AND deleted = b'0'

UPDATE plt_migration_batch
SET batch_status = 'RECONCILING',
    version = version + 1,
    update_time = CURRENT_TIMESTAMP(3)
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.batchId}
  AND batch_status = 'STAGED_READY'
  AND version = #{expectedVersion}
  AND deleted = b'0'
